      if (status === this.activeStatus) return
      this.activeStatus = status
      this.fetchOrders()
    },
    fetchOrders () {
      const requestId = (this._ordersRequestId || 0) + 1
      const status = this.activeStatus
      this._ordersRequestId = requestId
      this.loading = true
      mpx.request({
        url: '/api/orders',
        data: { status },
        success: ({ data }) => {
          if (this._ordersRequestId !== requestId || this.activeStatus !== status) return
          this.orders = data.list
          this.statusTabs = data.summary
        },
        complete: () => {
          if (this._ordersRequestId === requestId) {
            this.loading = false
          }
        }
      })
    },
    openOrder ({ detail }) {
      mpx.navigateTo({ url: `/pages/orders/detail?id=${detail.orderId}` })
    },
    removeOrder ({ detail }) {
      mpx.showModal({
        title: '删除订单',
        content: '删除后将无法在订单列表中查看，确认删除吗？',
        success: ({ confirm }) => {
          if (!confirm) return
          mpx.request({
            url: `/api/orders/${detail.orderId}`,
            method: 'DELETE',
            success: () => {
              this.orders = this.orders.filter(order => order.id !== detail.orderId)
            }
          })
        }
      })
    },
    handleConnectionChange ({ detail }) {
      if (!detail || detail.memberId !== this.memberId) return
      this.logisticsOnline = detail.connected
    },
    handleLogisticsMessage ({ detail }) {
      if (!detail || detail.memberId !== this.memberId) return
      this.orders = this.orders.map(order => {
        if (order.id !== detail.orderId) return order
        return Object.assign({}, order, {
          status: detail.status,
          statusText: detail.statusText,
          logisticsText: detail.logisticsText,
          updatedAt: detail.updatedAt
        })
      })
    },
    handleChannelError ({ detail }) {
      if (detail && detail.memberId && detail.memberId !== this.memberId) return
      this.logisticsOnline = false
    },
    goShopping () {
      mpx.switchTab({ url: '/pages/home/index' })
    }
  }
})
